'use strict';
const cases={
born2beroot:{eyebrow:'SERVER- & ADMINISTRATIONSPROJEKT / 12/2022',title:'Born2beroot — gehärteter Linux-Server',intro:'Einen Debian-Server in VirtualBox geplant, installiert, konfiguriert und abgesichert.',body:`<div class="case-grid"><section><h3>Server aufsetzen</h3><p>Debian als virtuelle Maschine in VirtualBox eingerichtet. Systemkonfiguration und administrative Vorgaben im eigenen Projekt umgesetzt.</p><h3>Absicherung</h3><p>SSH auf einem eigenen Port, Firewall-Regeln mit UFW sowie strenge Passwort- und sudo-Richtlinien konfiguriert. Der eigene SSH-Port ergänzt die Zugangskonfiguration; er ersetzt keine Zugangskontrolle.</p></section><section><h3>Monitoring & Dienste</h3><p>Ein Monitoring-Skript per cron zur laufenden Systemüberwachung eingesetzt. Im Bonus WordPress mit Lighttpd, MariaDB und PHP eingerichtet.</p><h3>Relevanz für Systemintegration</h3><p>Praktische Grundlage für Linux-Administration, Virtualisierung, sichere Konfiguration und regelmäßige Zustandskontrollen.</p></section></div><div class="tags"><span>Debian</span><span>VirtualBox</span><span>SSH</span><span>UFW</span><span>sudo</span><span>cron</span><span>Lighttpd / MariaDB / PHP</span></div>`},
inception:{eyebrow:'CONTAINERISIERTE INFRASTRUKTUR / 03/2025',title:'Inception — Dienste als verbundenes System',intro:'Einen vollständigen Web-Stack mit Docker Compose selbst aufgebaut: Nginx, WordPress und MariaDB in getrennten Containern.',body:`<div class="case-grid"><section><h3>Aufbau</h3><p>Die einzelnen Dienste mit Docker Compose verbunden. Alpine Linux als Teil der Containerumgebung verwendet; Zuständigkeiten zwischen Webserver, Anwendung und Datenbank getrennt.</p><h3>Konfiguration</h3><p>SSL/TLS am Nginx-Webserver, persistente Volumes für Daten, Docker-Netzwerke und geheime Zugangsdaten mit Secrets konfiguriert.</p></section><section><h3>Zusammenspiel verstehen</h3><p>Das Projekt verbindet Dienstkonfiguration, Kommunikation zwischen Containern, verschlüsselte Zugriffe und persistente Datenhaltung.</p><h3>Relevanz für Systemintegration</h3><p>Praxis mit voneinander abhängigen Diensten und reproduzierbarer Bereitstellung.</p></section></div><div class="tags"><span>Docker Compose</span><span>Nginx</span><span>TLS</span><span>WordPress</span><span>MariaDB</span><span>Alpine Linux</span><span>Volumes / Netzwerke / Secrets</span></div>`},
netpractice:{eyebrow:'NETZWERKGRUNDLAGEN / 10/2023',title:'NetPractice — IPv4 verstehen und Fehler finden',intro:'Zehn Netzwerk-Level mit IPv4, Subnetting und Routing gelöst.',body:`<div class="case-grid"><section><h3>Konfiguration</h3><p>Netzwerke mit Subnetzmasken in CIDR-Schreibweise, Switches, Routern und Routing-Tabellen konfiguriert.</p><h3>Fehleranalyse</h3><p>Fehlkonfigurationen analysiert und die Konnektivität innerhalb der vorgegebenen Netzwerkaufgaben hergestellt. Alle zehn Level gelöst.</p></section><section><h3>Relevanz für Systemintegration</h3><p>Adressierung, Subnetzgrenzen und Routen als Grundlage für die strukturierte Analyse von Erreichbarkeitsproblemen.</p><h3>Einordnung</h3><p>Konfigurations- und Übungsprojekt mit zehn gelösten Leveln. Der Schwerpunkt liegt auf nachvollziehbarer Adressierung und Erreichbarkeit.</p></section></div><div class="tags"><span>IPv4</span><span>Subnetting / CIDR</span><span>Routing</span><span>Fehleranalyse</span><span>10 Level</span></div>`},
transcendence:{eyebrow:'TEAMPROJEKT / 04/2025',title:'ft_transcendence — sichere Echtzeit-Plattform',intro:'Im Team eine Echtzeit-Plattform mit Django, WebSockets, PostgreSQL und Docker umgesetzt.',body:`<div class="case-grid"><section><h3>Authentifizierung</h3><p>Das Teamprojekt umfasst sichere Anmeldung mit OAuth 2.0, JWT und Zwei-Faktor-Authentifizierung.</p><h3>Echtzeit & Bereitstellung</h3><p>Echtzeit-Spiele über WebSockets und Betrieb der Anwendung in Docker-Containern.</p></section><section><h3>Relevanz für Systemintegration</h3><p>Zusammenspiel von Anwendung, Datenbank, Kommunikation und Anmeldung; Zusammenarbeit an einem System mit mehreren Komponenten.</p><h3>Mein Kontext</h3><p>Teamprojekt. Die beschriebenen Funktionen beziehen sich auf das gemeinsame Ergebnis; eine alleinige Implementierung aller Komponenten wird nicht behauptet.</p></section></div><div class="tags"><span>Django</span><span>WebSockets</span><span>PostgreSQL</span><span>Docker</span><span>OAuth 2.0 / JWT / 2FA</span><span>Teamarbeit</span></div>`},
irc:{eyebrow:'SERVER- & PROTOKOLLENTWICKLUNG / 02/2025',title:'ft_irc — ein eigener IRC-Server',intro:'Einen IRC-Server in C++98 mit TCP-Sockets entwickelt, kompatibel mit einem Standard-IRC-Client.',body:`<div class="case-grid"><section><h3>Umsetzung</h3><p>Serverentwicklung auf Basis von TCP-Sockets und des IRC-Protokolls. Die Kompatibilität mit einem Standard-IRC-Client war Teil des Projekts.</p></section><section><h3>Relevanz für Systemintegration</h3><p>Praktisches Verständnis für Client-Server-Kommunikation und Netzwerkdienste. Die Entwicklung eines Servers ergänzt die Administrationserfahrung aus Born2beroot.</p></section></div><div class="tags"><span>C++98</span><span>TCP-Sockets</span><span>IRC</span><span>Client-Server</span></div>`},

studio:{eyebrow:'PROJEKTPRAXIS / AUTOMATISIERUNG & INTEGRATION',title:'Scripts Studio',intro:'Eine lokale Arbeitsumgebung, die getrennte Medienwerkzeuge über eine gemeinsame Oberfläche und einen Python-Runner verbindet.',body:`<img src="/assets/studio-preview.png" alt="Tatsächliche Oberfläche von Scripts Studio"><div class="case-grid"><section><h3>Ausgangslage</h3><p>Einzelne Skripte hatten unterschiedliche Startpunkte und Eingaben. Ergebnisse mussten manuell zwischen Werkzeugen weitergegeben werden.</p><h3>Mein Beitrag</h3><p>Organisation der Werkzeuge in einer gemeinsamen Oberfläche: Videos erstellen, Clips suchen und herunterladen, Medien prüfen und Ausgaben bereinigen. Python- und PowerShell-Skripte sowie FFmpeg sind Teil der Projektumgebung.</p></section><section><h3>Bezug zur Systemintegration</h3><p>Externe Werkzeuge integrieren, wiederkehrende Schritte automatisieren und Fehler über Logs und Jobverlauf nachvollziehbar machen. Medienvalidierung, Prozessabbruch und eine Bereinigung mit Vorschau unterstützen kontrollierbare Abläufe.</p><h3>Einordnung</h3><p>Ein lokales Software- und Integrationsprojekt mit Schwerpunkt auf Prozesssteuerung und nachvollziehbaren Abläufen.</p></section></div><div class="tags"><span>Python</span><span>PowerShell</span><span>Prozesssteuerung</span><span>Logs & Fehlersuche</span><span>Tool-Integration</span></div>`},
airbcar:{eyebrow:'PROJEKTPRAXIS / ANWENDUNGSINTEGRATION / 2025',title:'AIRBCAR',intro:'Eine Mietwagenplattform, die Kunden und Vermietungen in Marokko verbindet.',body:`<div class="case-grid"><section><h3>Aufgabe & Beitrag</h3><p>UI/UX-Design und Frontend-Entwicklung sowie Arbeit an der Backend-Anbindung mit Django und PostgreSQL. Dazu gehörten Buchungsabläufe und rollenbasierte Zugriffssteuerung innerhalb der Anwendung.</p><h3>Technische Komponenten</h3><p>Django-APIs und PostgreSQL, ergänzt durch Supabase und Redis. Docker und GitHub Actions waren Teil der Bereitstellungsabläufe.</p></section><section><h3>Bezug zur Systemintegration</h3><p>Schnittstellen und Abhängigkeiten zwischen Anwendung, Datenhaltung und Bereitstellung verstehen. Die Projektpraxis bietet einen Ausgangspunkt für das spätere Lernen von Betrieb, Monitoring und strukturierter Störungsanalyse.</p><h3>Einordnung</h3><p>Das Projekt verbindet Oberflächen, APIs, Datenhaltung und Bereitstellung. Die ergänzenden Infrastrukturprojekte zeigen meine Server- und Netzwerkpraxis.</p></section></div><div class="tags"><span>API-Integration</span><span>PostgreSQL</span><span>Docker</span><span>GitHub Actions</span><span>Anwendungsrollen</span></div><p class="case-note">Projektangaben beruhen auf meinem bisherigen Portfolio.</p>`},
lab:{eyebrow:'GEPLANT / LERNPFAD IT-SYSTEMINTEGRATION',title:'Infrastruktur-Lab: vom Plan zum Nachweis.',intro:'Geplante Erweiterung meiner bestehenden Linux-, Container- und Netzwerkpraxis. Dieses zusätzliche Lab ist noch nicht umgesetzt; die folgenden Punkte sind Lernziele und geplante Nachweise.',body:`<p class="case-note">Status: Planung. Aufbauend auf meinen bestehenden Projekten möchte ich Identitätsverwaltung und Betriebsabläufe in einer gemeinsamen Testumgebung erproben.</p><figure class="lab-map"><figcaption>Geplantes Lab — Zielarchitektur, noch nicht aufgebaut</figcaption><svg viewBox="0 0 660 190" role="img" aria-label="Geplante Testumgebung: Windows-Client, internes Testnetz, Windows- und Linux-Server sowie Monitoring und Backup"><g fill="none" stroke="#6aafa3" stroke-width="2"><path d="M150 90H255M325 60V32H480V60M325 120V157H480V120"/></g><g fill="#142e3e" stroke="#5a8b8c"><rect x="10" y="60" width="140" height="60" rx="6"/><rect x="255" y="60" width="140" height="60" rx="6"/><rect x="410" y="6" width="240" height="55" rx="6"/><rect x="410" y="126" width="240" height="55" rx="6"/></g><g fill="#dcf5ed" font-family="Segoe UI, sans-serif" font-size="14" text-anchor="middle"><text x="80" y="85">Windows-Client</text><text x="80" y="105">Testbenutzer</text><text x="325" y="85">Internes Testnetz</text><text x="325" y="105">DNS / DHCP</text><text x="530" y="30">Windows / Linux</text><text x="530" y="49">Identitäten / Dienste</text><text x="530" y="150">Monitoring / Backup</text><text x="530" y="169">Alarm / Restore-Test</text></g></svg></figure><div class="case-grid"><section><h3>01 / Netzwerke & Virtualisierung</h3><p>Isolierte virtuelle Testumgebung mit IP-Plan, Subnetzen, DNS und DHCP aufbauen. Nachweis: Netzplan und dokumentierte Diagnose einer gestörten Namensauflösung.</p><h3>02 / Windows & Identitäten</h3><p>Windows Server und Client mit Active Directory, Testkonten, Gruppen, Freigaben und Gruppenrichtlinien verbinden. Nachweis: Berechtigungsmatrix, On-/Offboarding-Checkliste und Zugriffstests.</p><h3>03 / Linux & Automatisierung</h3><p>Linux-Dienst betreiben, Rechte und Updates prüfen sowie Inventar- und Zustandsberichte per PowerShell/Python erstellen. Nachweis: Konfiguration, Skript und nachvollziehbarer Testlauf.</p></section><section><h3>04 / Monitoring & IT-Support</h3><p>Verfügbarkeit beobachten und einen kontrollierten Dienstausfall untersuchen. Nachweis: Ticket mit Symptom, Diagnose, Ursache, Lösung und verständlicher Anwenderinformation.</p><h3>05 / Sicherheit & Wiederherstellung</h3><p>Zugriffe begrenzen, Patchstand dokumentieren und Backup/Wiederherstellung erproben. Nachweis: Wiederherstellungsprotokoll mit Prüfergebnis; ein Snapshot allein ist kein Backup-Nachweis.</p><h3>06 / Microsoft 365 & Übergabe</h3><p>Benutzer-, Lizenz- und Identitätsgrundlagen in Microsoft 365/Entra ID lernen, sofern eine geeignete Testumgebung verfügbar ist. Nachweis: dokumentierter Testablauf und kurze Betriebsanleitung.</p></section></div><p class="case-note">Aufbauend auf Born2beroot, Inception und NetPractice: zuerst eine gemeinsame Testumgebung dokumentieren, danach Windows/AD und einen geprüften Restore ergänzen. Erst tatsächlich geprüfte Ergebnisse werden als Projektpraxis veröffentlicht.</p>`}
};
const dialog=document.querySelector('#project-dialog');
let opener;
function openProject(id){const p=cases[id];if(!p)return;opener=document.activeElement;document.querySelector('#case-content').innerHTML=`<p class="eyebrow">${p.eyebrow}</p><h2>${p.title}</h2><p>${p.intro}</p>${p.body}`;if(!dialog.open)dialog.showModal();}
document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>openProject(b.dataset.project)));
document.addEventListener('projectselect',e=>openProject(e.detail));
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('close',()=>opener?.focus());
dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))dialog.close();});
const views=['home','work','systems','about','contact'];
function navigate(view){if(!views.includes(view))view='home';document.body.dataset.view=view;document.querySelectorAll('.story-panel[data-view]').forEach(p=>p.hidden=p.dataset.view!==view);document.querySelectorAll('.destination-nav button').forEach(b=>{if(b.dataset.go===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});document.querySelector('#sector').textContent=`STATION 0${views.indexOf(view)} / ${({home:'START',work:'PROJEKTE',systems:'LERNPFAD',about:'PROFIL',contact:'KONTAKT'})[view]}`;document.querySelector('main').scrollTop=0;document.dispatchEvent(new CustomEvent('worldnavigate',{detail:view}));}
document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>{if(location.hash==='#'+b.dataset.go)navigate(b.dataset.go);else location.hash=b.dataset.go;}));
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
navigate(location.hash.slice(1));
document.querySelector('#read-mode').addEventListener('click',e=>{const on=document.body.classList.toggle('reading');e.currentTarget.setAttribute('aria-pressed',String(on));e.currentTarget.textContent=on?'Zurück zur 3D-Ansicht':'Leseansicht';});
